// Boss sprites as base64 data URIs.
// The PNG sources live in public/assets/IronWarden.png and
// public/assets/Bombardier.png, but snapshot pushes carry text only,
// so the shipped game loads the art from here instead of the files.
// Regenerate with: base64 -w0 public/assets/<Name>.png
export const IRON_WARDEN_DATA_URI = 'data:image/png;base64,' + "";

export const BOMBARDIER_DATA_URI = 'data:image/png;base64,' + "";
